/**
 * Instalador Automatizado: Módulo de Compras y SIRE (RVIE / RCE) con Control Antiduplicados
 * Proyecto: AYSunat - Sistema Contable y Tributario Peruano
 * 
 * Genera y actualiza:
 * - src/modules/purchases/ (tipos, servicio con control de duplicados por proveedor, serie, correlativo y periodo)
 * - src/modules/sire/ (tipos, CAR 27 dígitos, detector de duplicados, generador RVIE, generador RCE, orquestador)
 * - src/modules/__tests__/ (pruebas de integración de Compras, SIRE y control estricto de duplicados)
 */

const fs = require("fs");
const path = require("path");

const files = {
  "src/modules/purchases/types.ts": "import { CurrencyCode, IdentityDocTypeCode } from \"../../core/tax-engine/types.js\";\n\n/**\n * Destino del Crédito Fiscal en Compras según Ley del IGV (TUO D.S. 055-99-EF):\n * - GRAVADO_EXCLUSIVO: Adquisiciones destinadas exclusivamente a operaciones gravadas y de exportación (100% crédito fiscal).\n * - GRAVADO_COMUN: Adquisiciones destinadas a operaciones gravadas y no gravadas (sujeto a prorrata de crédito fiscal).\n * - GRAVADO_SIN_CREDITO: Adquisiciones gravadas destinadas exclusivamente a operaciones no gravadas (costo/gasto, sin crédito fiscal).\n * - NO_GRAVADO: Adquisiciones no gravadas, exoneradas o inafectas.\n */\nexport type PurchaseTaxDestination =\n  | \"GRAVADO_EXCLUSIVO\"\n  | \"GRAVADO_COMUN\"\n  | \"GRAVADO_SIN_CREDITO\"\n  | \"NO_GRAVADO\";\n\n/**\n * Clasificación de Bienes y Servicios según Tabla 31 de SUNAT (SIRE RCE):\n * 1: Mercaderías, materia prima, insumos\n * 2: Activo fijo\n * 3: Otros costos de producción o gastos de administración/ventas\n * 4: Gastos no deducibles\n * 5: Contratos de construcción\n */\nexport type PurchaseExpenseClassification = \"1\" | \"2\" | \"3\" | \"4\" | \"5\";\n\nexport interface SupplierProfile {\n  id?: string;\n  docType: IdentityDocTypeCode; // \"6\" para RUC\n  docNumber: string;\n  name: string; // Razón Social\n  tradeName?: string;\n  isHabido?: boolean;\n  isActive?: boolean;\n  address?: string;\n  email?: string;\n}\n\nexport interface PurchaseItemInput {\n  id?: string;\n  description: string;\n  quantity: number | string;\n  unitValue: number | string; // Valor neto sin IGV\n  taxDestination: PurchaseTaxDestination;\n  classification?: PurchaseExpenseClassification;\n  igvRate?: number | string; // Default: 0.18\n}\n\nexport interface PurchaseCalculatedItem {\n  id?: string;\n  description: string;\n  quantity: string;\n  unitValue: string;\n  netBase: string;\n  igvAmount: string;\n  totalAmount: string;\n  taxDestination: PurchaseTaxDestination;\n  classification: PurchaseExpenseClassification;\n  hasFiscalCredit: boolean;\n}\n\nexport interface DetractionData {\n  hasDetraction: boolean;\n  detractionCode?: string; // Código de servicio o bien según D.L. 940\n  detractionPercentage?: number | string;\n  detractionAmount?: number | string;\n  depositDate?: string; // \"YYYY-MM-DD\"\n  depositProofNumber?: string; // Número de constancia del Banco de la Nación\n}\n\nexport interface PurchaseDocumentInput {\n  companyRuc: string; // RUC de la empresa compradora\n  supplier: SupplierProfile;\n  docType: \"01\" | \"03\" | \"07\" | \"08\" | \"50\"; // 01: Factura, 03: Boleta, 07: NC, 08: ND, 50: DUA\n  series: string; // Serie del emisor (ej. F001, E001)\n  correlative: number | string; // Correlativo del emisor\n  issueDate: string; // \"YYYY-MM-DD\"\n  dueDate?: string; // \"YYYY-MM-DD\"\n  accountingPeriod: string; // \"YYYY-MM\" Período en el que se anota en el RCE\n  currency: CurrencyCode;\n  exchangeRate?: number | string; // Requerido si currency === \"USD\"\n  paymentMethod: \"CONTADO\" | \"CREDITO\";\n  isBancarizado?: boolean; // True si se pagó mediante medio bancario (bancarización)\n  bancarizacionMedium?: string; // Depósito en cuenta, transferencia, etc.\n  detraction?: DetractionData;\n  retentionApplied?: boolean;\n  retentionAmount?: number | string;\n  modifiedDocument?: {\n    docType: \"01\" | \"03\" | \"50\";\n    series: string;\n    correlative: number | string;\n    issueDate: string;\n  };\n  items: PurchaseItemInput[];\n}\n\nexport interface PurchaseTotals {\n  baseGravadaExclusiva: string; // Casilla 107\n  igvGravadoExclusivo: string; // Casilla 108\n  baseGravadaComun: string; // Casilla 110\n  igvGravadoComun: string; // Casilla 111\n  baseGravadaSinCredito: string; // Casilla 113\n  igvGravadoSinCredito: string; // Casilla 114\n  adquisicionesNoGravadas: string; // Exoneradas/Inafectas\n  isc: string;\n  icbper: string;\n  otrosCargos: string;\n  totalAdquisicion: string;\n  totalCreditoFiscal: string; // Suma de IGV con derecho a crédito fiscal\n}\n\nexport interface PurchaseDocumentRecord {\n  id: string;\n  car: string; // Código de Anotación de Registro de 27 caracteres\n  companyRuc: string;\n  accountingPeriod: string; // \"YYYY-MM\"\n  supplier: SupplierProfile;\n  docType: \"01\" | \"03\" | \"07\" | \"08\" | \"50\";\n  series: string;\n  correlative: string;\n  fullNumber: string; // Serie-Correlativo\n  issueDate: string;\n  dueDate?: string;\n  currency: CurrencyCode;\n  exchangeRate?: string;\n  paymentMethod: \"CONTADO\" | \"CREDITO\";\n  isBancarizado: boolean;\n  detraction?: DetractionData;\n  canUseFiscalCredit: boolean;\n  fiscalCreditRestrictionReason?: string;\n  totals: PurchaseTotals;\n  items: PurchaseCalculatedItem[];\n  sireStatus: \"PROPUESTA_PENDIENTE\" | \"ACEPTADO\" | \"COMPLEMENTADO\" | \"EXCLUIDO\";\n  createdAt: string;\n}\n\nexport interface MonthlyPurchasesSummary {\n  period: string;\n  totalDocuments: number;\n  baseGravadaExclusivaTotal: string;\n  igvGravadoExclusivoTotal: string;\n  baseGravadaComunTotal: string;\n  igvGravadoComunTotal: string;\n  baseGravadaSinCreditoTotal: string;\n  igvGravadoSinCreditoTotal: string;\n  adquisicionesNoGravadasTotal: string;\n  totalAdquisiciones: string;\n  totalCreditoFiscalAceptado: string;\n}\n",
  "src/modules/purchases/purchase-service.ts": "import { Decimal } from \"decimal.js\";\nimport {\n  PurchaseDocumentInput,\n  PurchaseDocumentRecord,\n  PurchaseCalculatedItem,\n  PurchaseTotals,\n  MonthlyPurchasesSummary,\n  SupplierProfile,\n} from \"./types.js\";\nimport { validateRuc } from \"../../core/tax-engine/validators.js\";\nimport { normalizeDuplicateKey } from \"../sire/duplicate-detector.js\";\n\nDecimal.set({ precision: 24, rounding: Decimal.ROUND_HALF_UP });\nconst ZERO = new Decimal(0);\nconst round = (val: Decimal) => val.toDecimalPlaces(2, Decimal.ROUND_HALF_UP);\n\nexport function buildCarCode(\n  issuerRuc: string,\n  cpeType: string,\n  series: string,\n  correlative: number | string\n): string {\n  const cleanRuc = issuerRuc.trim().padStart(11, \"0\").slice(-11);\n  const cleanType = cpeType.trim().padStart(2, \"0\").slice(-2);\n  const cleanSeries = series.trim().toUpperCase().padStart(4, \"0\").slice(-4);\n  const cleanCorrelative = String(correlative).replace(/\\D/g, \"\").padStart(10, \"0\").slice(-10);\n  return `${cleanRuc}${cleanType}${cleanSeries}${cleanCorrelative}`;\n}\n\nexport function calculateMonthsDifference(issueDateStr: string, accountingPeriodStr: string): number {\n  const [issueYear, issueMonth] = issueDateStr.split(\"-\").map(Number);\n  const [accYear, accMonth] = accountingPeriodStr.split(\"-\").map(Number);\n  return (accYear - issueYear) * 12 + (accMonth - issueMonth);\n}\n\nexport class PurchaseService {\n  private purchases: Map<string, PurchaseDocumentRecord> = new Map();\n  private purchasesByPeriodKey: Map<string, PurchaseDocumentRecord> = new Map();\n  private suppliers: Map<string, SupplierProfile> = new Map();\n\n  public registerSupplier(supplier: SupplierProfile): SupplierProfile {\n    const rucErrors = validateRuc(supplier.docNumber);\n    if (supplier.docType === \"6\" && rucErrors.length > 0) {\n      throw new Error(`RUC de proveedor inválido: ${rucErrors.join(\", \")}`);\n    }\n    const record: SupplierProfile = {\n      ...supplier,\n      id: supplier.id || `prov-${supplier.docNumber}`,\n      isHabido: supplier.isHabido ?? true,\n      isActive: supplier.isActive ?? true,\n    };\n    this.suppliers.set(supplier.docNumber, record);\n    return record;\n  }\n\n  public getSupplier(docNumber: string): SupplierProfile | undefined {\n    return this.suppliers.get(docNumber);\n  }\n\n  public registerPurchase(input: PurchaseDocumentInput): PurchaseDocumentRecord {\n    // 1. Validar RUC del emisor/proveedor\n    if (input.supplier.docType === \"6\") {\n      const rucErrors = validateRuc(input.supplier.docNumber);\n      if (rucErrors.length > 0) {\n        throw new Error(`Error en el proveedor: ${rucErrors.join(\", \")}`);\n      }\n    }\n    this.registerSupplier(input.supplier);\n\n    // 2. Validar formato de período y fecha\n    if (!/^\\d{4}-\\d{2}$/.test(input.accountingPeriod)) {\n      throw new Error(`Período contable inválido: ${input.accountingPeriod}. Formato esperado: YYYY-MM.`);\n    }\n    if (!/^\\d{4}-\\d{2}-\\d{2}$/.test(input.issueDate)) {\n      throw new Error(`Fecha de emisión inválida: ${input.issueDate}. Formato esperado: YYYY-MM-DD.`);\n    }\n\n    if (input.currency === \"USD\" && (!input.exchangeRate || Number(input.exchangeRate) <= 0)) {\n      throw new Error(\"Comprobantes de compra en USD requieren tipo de cambio positivo.\");\n    }\n\n    if (!input.items || input.items.length === 0) {\n      throw new Error(\"El comprobante de compra debe tener al menos un ítem.\");\n    }\n\n    // 3. Generar CAR determinista SUNAT y verificar duplicidad por proveedor, serie, número y período\n    const car = buildCarCode(input.supplier.docNumber, input.docType, input.series, input.correlative);\n\n    const periodDuplicateKey = normalizeDuplicateKey(\n      input.supplier.docNumber,\n      input.docType,\n      input.series,\n      input.correlative,\n      input.accountingPeriod\n    );\n\n    if (this.purchasesByPeriodKey.has(periodDuplicateKey)) {\n      throw new Error(\n        `El comprobante de compra con CAR ${car} (${input.series}-${input.correlative}) ya está registrado para el proveedor ${input.supplier.docNumber} en el periodo ${input.accountingPeriod}.`\n      );\n    }\n\n    if (this.purchases.has(car)) {\n      throw new Error(`El comprobante de compra con CAR ${car} (${input.series}-${input.correlative}) ya está registrado.`);\n    }\n\n    // 4. Calcular ítems y desgloses\n    let baseGravadaExclusiva = ZERO;\n    let igvGravadoExclusivo = ZERO;\n    let baseGravadaComun = ZERO;\n    let igvGravadoComun = ZERO;\n    let baseGravadaSinCredito = ZERO;\n    let igvGravadoSinCredito = ZERO;\n    let noGravadas = ZERO;\n\n    const calculatedItems: PurchaseCalculatedItem[] = input.items.map((it, idx) => {\n      const qty = new Decimal(it.quantity);\n      const val = new Decimal(it.unitValue);\n      const netBase = round(qty.mul(val));\n      const rate = new Decimal(it.igvRate ?? 0.18);\n      const isGravado = it.taxDestination !== \"NO_GRAVADO\";\n      const igv = isGravado ? round(netBase.mul(rate)) : ZERO;\n      const total = round(netBase.plus(igv));\n\n      const hasFiscalCredit = it.taxDestination === \"GRAVADO_EXCLUSIVO\" || it.taxDestination === \"GRAVADO_COMUN\";\n\n      if (it.taxDestination === \"GRAVADO_EXCLUSIVO\") {\n        baseGravadaExclusiva = baseGravadaExclusiva.plus(netBase);\n        igvGravadoExclusivo = igvGravadoExclusivo.plus(igv);\n      } else if (it.taxDestination === \"GRAVADO_COMUN\") {\n        baseGravadaComun = baseGravadaComun.plus(netBase);\n        igvGravadoComun = igvGravadoComun.plus(igv);\n      } else if (it.taxDestination === \"GRAVADO_SIN_CREDITO\") {\n        baseGravadaSinCredito = baseGravadaSinCredito.plus(netBase);\n        igvGravadoSinCredito = igvGravadoSinCredito.plus(igv);\n      } else {\n        noGravadas = noGravadas.plus(netBase);\n      }\n\n      return {\n        id: it.id || `item-${idx + 1}`,\n        description: it.description,\n        quantity: qty.toFixed(4),\n        unitValue: round(val).toFixed(2),\n        netBase: netBase.toFixed(2),\n        igvAmount: igv.toFixed(2),\n        totalAmount: total.toFixed(2),\n        taxDestination: it.taxDestination,\n        classification: it.classification || \"1\",\n        hasFiscalCredit,\n      };\n    });\n\n    const totalAdquisicion = round(\n      baseGravadaExclusiva\n        .plus(igvGravadoExclusivo)\n        .plus(baseGravadaComun)\n        .plus(igvGravadoComun)\n        .plus(baseGravadaSinCredito)\n        .plus(igvGravadoSinCredito)\n        .plus(noGravadas)\n    );\n\n    // 5. Validaciones de Crédito Fiscal\n    let canUseFiscalCredit = true;\n    let restrictionReason: string | undefined;\n\n    // A. Boletas de venta (03) no dan derecho a crédito fiscal\n    if (input.docType === \"03\") {\n      canUseFiscalCredit = false;\n      restrictionReason = \"Las boletas de venta recibidas no otorgan derecho a crédito fiscal del IGV.\";\n    }\n\n    // B. Antigüedad máxima de 12 meses para crédito fiscal (Art. 19 Ley IGV)\n    const monthsDiff = calculateMonthsDifference(input.issueDate, input.accountingPeriod);\n    if (monthsDiff > 12) {\n      canUseFiscalCredit = false;\n      restrictionReason = `El comprobante tiene ${monthsDiff} meses de antigüedad respecto al período contable, superando el límite legal de 12 meses para ejercer el crédito fiscal (Art. 19 Ley del IGV).`;\n    }\n\n    // C. Bancarización obligatoria (Ley 28194)\n    const bancarizacionThreshold = input.currency === \"USD\" ? new Decimal(500) : new Decimal(2000);\n    const requiresBancarizacion = totalAdquisicion.gte(bancarizacionThreshold);\n    const isBancarizado = input.isBancarizado ?? false;\n\n    if (requiresBancarizacion && !isBancarizado) {\n      canUseFiscalCredit = false;\n      restrictionReason = `Operación por ${totalAdquisicion.toFixed(2)} ${input.currency} supera el umbral de bancarización y no cuenta con medio de pago bancario (Ley 28194).`;\n    }\n\n    // D. Detracciones SPOT (D.L. 940)\n    if (input.detraction?.hasDetraction) {\n      if (!input.detraction.depositProofNumber || !input.detraction.depositDate) {\n        canUseFiscalCredit = false;\n        restrictionReason = \"Operación sujeta a SPOT sin depósito de detracción verificado. El crédito fiscal queda suspendido hasta el pago efectivo (D.L. 940).\";\n      }\n    }\n\n    const totalFiscalCredit = canUseFiscalCredit ? round(igvGravadoExclusivo.plus(igvGravadoComun)) : ZERO;\n\n    const totals: PurchaseTotals = {\n      baseGravadaExclusiva: round(baseGravadaExclusiva).toFixed(2),\n      igvGravadoExclusivo: round(igvGravadoExclusivo).toFixed(2),\n      baseGravadaComun: round(baseGravadaComun).toFixed(2),\n      igvGravadoComun: round(igvGravadoComun).toFixed(2),\n      baseGravadaSinCredito: round(baseGravadaSinCredito).toFixed(2),\n      igvGravadoSinCredito: round(igvGravadoSinCredito).toFixed(2),\n      adquisicionesNoGravadas: round(noGravadas).toFixed(2),\n      isc: \"0.00\",\n      icbper: \"0.00\",\n      otrosCargos: \"0.00\",\n      totalAdquisicion: totalAdquisicion.toFixed(2),\n      totalCreditoFiscal: totalFiscalCredit.toFixed(2),\n    };\n\n    const record: PurchaseDocumentRecord = {\n      id: `purch-${Date.now()}-${Math.floor(Math.random() * 1000)}`,\n      car,\n      companyRuc: input.companyRuc,\n      accountingPeriod: input.accountingPeriod,\n      supplier: input.supplier,\n      docType: input.docType,\n      series: input.series.toUpperCase(),\n      correlative: String(input.correlative).padStart(8, \"0\"),\n      fullNumber: `${input.series.toUpperCase()}-${String(input.correlative).padStart(8, \"0\")}`,\n      issueDate: input.issueDate,\n      dueDate: input.dueDate,\n      currency: input.currency,\n      exchangeRate: input.exchangeRate ? new Decimal(input.exchangeRate).toFixed(4) : undefined,\n      paymentMethod: input.paymentMethod,\n      isBancarizado,\n      detraction: input.detraction,\n      canUseFiscalCredit,\n      fiscalCreditRestrictionReason: restrictionReason,\n      totals,\n      items: calculatedItems,\n      sireStatus: \"PROPUESTA_PENDIENTE\",\n      createdAt: new Date().toISOString(),\n    };\n\n    this.purchases.set(car, record);\n    this.purchasesByPeriodKey.set(periodDuplicateKey, record);\n    return record;\n  }\n\n\n  public hasPurchase(\n    supplierDocNumber: string,\n    docType: string,\n    series: string,\n    correlative: number | string,\n    accountingPeriod: string\n  ): boolean {\n    const key = normalizeDuplicateKey(\n      supplierDocNumber,\n      docType,\n      series,\n      correlative,\n      accountingPeriod\n    );\n    return this.purchasesByPeriodKey.has(key);\n  }\n\n  public findByCar(car: string): PurchaseDocumentRecord | undefined {\n    return this.purchases.get(car);\n  }\n\n  public listByPeriod(period: string, companyRuc?: string): PurchaseDocumentRecord[] {\n    return Array.from(this.purchases.values()).filter((p) => {\n      const matchPeriod = p.accountingPeriod === period;\n      const matchCompany = companyRuc ? p.companyRuc === companyRuc : true;\n      return matchPeriod && matchCompany;\n    });\n  }\n\n  public updateSireStatus(\n    car: string,\n    status: PurchaseDocumentRecord[\"sireStatus\"]\n  ): PurchaseDocumentRecord {\n    const record = this.purchases.get(car);\n    if (!record) {\n      throw new Error(`Comprobante de compra con CAR ${car} no encontrado.`);\n    }\n    record.sireStatus = status;\n    return record;\n  }\n\n  public getMonthlySummary(period: string, companyRuc?: string): MonthlyPurchasesSummary {\n    const periodPurchases = this.listByPeriod(period, companyRuc).filter(\n      (p) => p.sireStatus !== \"EXCLUIDO\"\n    );\n\n    let baseExclusiva = ZERO;\n    let igvExclusivo = ZERO;\n    let baseComun = ZERO;\n    let igvComun = ZERO;\n    let baseSinCredito = ZERO;\n    let igvSinCredito = ZERO;\n    let noGravadas = ZERO;\n    let totalAdq = ZERO;\n    let creditoFiscalAceptado = ZERO;\n\n    for (const p of periodPurchases) {\n      baseExclusiva = baseExclusiva.plus(p.totals.baseGravadaExclusiva);\n      igvExclusivo = igvExclusivo.plus(p.totals.igvGravadoExclusivo);\n      baseComun = baseComun.plus(p.totals.baseGravadaComun);\n      igvComun = igvComun.plus(p.totals.igvGravadoComun);\n      baseSinCredito = baseSinCredito.plus(p.totals.baseGravadaSinCredito);\n      igvSinCredito = igvSinCredito.plus(p.totals.igvGravadoSinCredito);\n      noGravadas = noGravadas.plus(p.totals.adquisicionesNoGravadas);\n      totalAdq = totalAdq.plus(p.totals.totalAdquisicion);\n\n      if (p.canUseFiscalCredit) {\n        creditoFiscalAceptado = creditoFiscalAceptado.plus(p.totals.totalCreditoFiscal);\n      }\n    }\n\n    return {\n      period,\n      totalDocuments: periodPurchases.length,\n      baseGravadaExclusivaTotal: round(baseExclusiva).toFixed(2),\n      igvGravadoExclusivoTotal: round(igvExclusivo).toFixed(2),\n      baseGravadaComunTotal: round(baseComun).toFixed(2),\n      igvGravadoComunTotal: round(igvComun).toFixed(2),\n      baseGravadaSinCreditoTotal: round(baseSinCredito).toFixed(2),\n      igvGravadoSinCreditoTotal: round(igvSinCredito).toFixed(2),\n      adquisicionesNoGravadasTotal: round(noGravadas).toFixed(2),\n      totalAdquisiciones: round(totalAdq).toFixed(2),\n      totalCreditoFiscalAceptado: round(creditoFiscalAceptado).toFixed(2),\n    };\n  }\n}\n",
  "src/modules/purchases/index.ts": "export * from './types.js';\nexport * from './purchase-service.js';\n",
  "src/modules/sire/types.ts": "/**\n * SISTEMA INTEGRADO DE REGISTROS ELECTRÓNICOS (SIRE - SUNAT)\n * Normativa: R.S. N° 112-2021/SUNAT, R.S. N° 040-2022/SUNAT y modificatorias\n */\n\nexport type SireBookCode = \"140400\" | \"080400\"; // 140400: RVIE, 080400: RCE\n\nexport interface SireFileNameParams {\n  ruc: string; // 11 dígitos\n  year: number | string; // 4 dígitos\n  month: number | string; // 2 dígitos (01 - 12)\n  bookCode: SireBookCode;\n  opportunityCode?: string; // \"02\" para reemplazo/propuesta SIRE (default)\n  hasInformation?: boolean; // true: \"1\" (con datos), false: \"0\" (sin operaciones)\n  currencyIndicator?: \"1\" | \"2\"; // 1: PEN (default), 2: USD\n  generatorIndicator?: \"1\" | \"2\"; // 2: SIRE Web / Cliente (default)\n  extension?: \"txt\" | \"zip\";\n}\n\nexport type SireProposalAction = \"ACEPTAR\" | \"COMPLEMENTAR\" | \"REEMPLAZAR\" | \"EXCLUIR\";\n\nexport interface SireCarParsed {\n  issuerRuc: string;\n  cpeType: string;\n  series: string;\n  correlative: string;\n  rawCar: string;\n}\n\nexport interface SireRvieLineData {\n  companyRuc: string;\n  companyName: string;\n  period: string; // \"YYYYMM\"\n  car?: string;\n  issueDate: string; // \"DD/MM/YYYY\"\n  dueDate?: string;\n  cpeType: string; // \"01\", \"03\", \"07\"\n  series: string;\n  correlative: string;\n  correlativeEnd?: string;\n  clientDocType: string; // \"6\", \"1\", \"0\", etc.\n  clientDocNumber: string;\n  clientName: string;\n  exportBase?: string;\n  taxableBase: string;\n  baseDiscount?: string;\n  igvAmount: string;\n  igvDiscount?: string;\n  exoneratedAmount?: string;\n  inaffectedAmount?: string;\n  iscAmount?: string;\n  ivapBase?: string;\n  ivapAmount?: string;\n  icbperAmount?: string;\n  otherTaxes?: string;\n  totalAmount: string;\n  currency: string;\n  exchangeRate?: string;\n  modifiedIssueDate?: string;\n  modifiedCpeType?: string;\n  modifiedSeries?: string;\n  modifiedCorrelative?: string;\n  cancellationIndicator?: string;\n  statusCode?: string; // \"1\": Válido, \"2\": Anulado\n}\n\nexport interface SireRceLineData {\n  companyRuc: string;\n  companyName: string;\n  period: string; // \"YYYYMM\"\n  car: string; // 27 caracteres del emisor/proveedor\n  issueDate: string; // \"DD/MM/YYYY\"\n  dueDate?: string;\n  cpeType: string; // \"01\", \"03\", \"07\", etc.\n  series: string;\n  duaYear?: string;\n  correlative: string;\n  correlativeEnd?: string;\n  supplierDocType: string; // \"6\"\n  supplierDocNumber: string;\n  supplierName: string;\n  baseGravadaExclusiva: string; // Adquisiciones gravadas exclusivamente a ventas gravadas\n  igvGravadoExclusivo: string;\n  baseGravadaComun?: string; // Adquisiciones gravadas a ventas comunes\n  igvGravadoComun?: string;\n  baseGravadaSinCredito?: string; // Adquisiciones gravadas sin derecho a crédito fiscal\n  igvGravadoSinCredito?: string;\n  adquisicionesNoGravadas?: string; // Exoneradas o inafectas\n  iscAmount?: string;\n  icbperAmount?: string;\n  otherTaxes?: string;\n  totalAmount: string;\n  currency: string;\n  exchangeRate?: string;\n  modifiedIssueDate?: string;\n  modifiedCpeType?: string;\n  modifiedSeries?: string;\n  modifiedCorrelative?: string;\n  detractionDepositDate?: string;\n  detractionProofNumber?: string;\n  retentionIndicator?: string;\n  classificationCode?: string; // \"1\" a \"5\"\n  bancarizadoIndicator?: string; // \"1\": Sí, \"0\": No\n  statusCode?: string; // \"1\": En el período, \"0\": Anulado\n}\n\nexport interface SireExportResult {\n  bookCode: SireBookCode;\n  bookName: string;\n  period: string;\n  fileName: string;\n  txtContent: string;\n  zipFileName?: string;\n  zipBuffer?: Uint8Array;\n  lineCount: number;\n  totalTaxableBase: string;\n  totalIgv: string;\n  totalAmount: string;\n}\n\nexport interface SireSettlementIntegrationPayload {\n  period: string; // \"YYYY-MM\"\n  salesTaxableBase: string;\n  salesIgv: string;\n  purchasesTaxableBase: string;\n  purchasesIgv: string;\n  purchasesCount: number;\n  salesCount: number;\n}\n\nexport interface SireCpeInput {\n  id?: string;\n  companyId?: string;\n  companyRuc: string;\n  cpeType: string;\n  series: string;\n  correlative: number | string;\n  fullNumber?: string;\n  issueDate: string;\n  dueDate?: string;\n  currency: string;\n  exchangeRate?: string;\n  clientDocType: string;\n  clientDocNumber: string;\n  clientName: string;\n  taxableBase: string;\n  igvAmount: string;\n  totalAmount: string;\n  status: string;\n  createdAt?: string;\n  updatedAt?: string;\n}\n",
  "src/modules/sire/car-generator.ts": "import { SireCarParsed } from \"./types.js\";\nimport { validateRuc } from \"../../core/tax-engine/validators.js\";\n\n/**\n * Generador y Validador del Código de Anotación de Registro (CAR) de SUNAT (27 caracteres)\n * Estructura:\n * - 01-11: RUC del emisor (11 dígitos)\n * - 12-13: Tipo de Comprobante (2 dígitos: 01, 03, 07, 08, etc.)\n * - 14-17: Serie del Comprobante (4 caracteres alfanuméricos)\n * - 18-27: Número Correlativo (10 dígitos con ceros a la izquierda)\n */\nexport function buildSireCar(\n  issuerRuc: string,\n  cpeType: string,\n  series: string,\n  correlative: number | string\n): string {\n  const cleanRuc = issuerRuc.trim().padStart(11, \"0\").slice(-11);\n  const cleanType = cpeType.trim().padStart(2, \"0\").slice(-2);\n  const cleanSeries = series.trim().toUpperCase().padStart(4, \"0\").slice(-4);\n  const cleanCorrelative = String(correlative).replace(/\\D/g, \"\").padStart(10, \"0\").slice(-10);\n\n  const car = `${cleanRuc}${cleanType}${cleanSeries}${cleanCorrelative}`;\n  if (car.length !== 27) {\n    throw new Error(`El CAR generado debe tener exactamente 27 caracteres. Resultó: ${car} (${car.length})`);\n  }\n  return car;\n}\n\nexport function validateSireCar(car: string): string[] {\n  const errors: string[] = [];\n  if (!car || typeof car !== \"string\") {\n    errors.push(\"El CAR no puede estar vacío.\");\n    return errors;\n  }\n  if (car.length !== 27) {\n    errors.push(`El CAR debe tener exactamente 27 caracteres (longitud actual: ${car.length}).`);\n  }\n  const rucPart = car.slice(0, 11);\n  const rucErrors = validateRuc(rucPart);\n  if (rucErrors.length > 0) {\n    errors.push(`RUC emisor en CAR inválido: ${rucErrors.join(\", \")}`);\n  }\n  const typePart = car.slice(11, 13);\n  if (!/^[0-9]{2}$/.test(typePart)) {\n    errors.push(`Tipo de CPE en CAR inválido: ${typePart}`);\n  }\n  const seriesPart = car.slice(13, 17);\n  if (!/^[A-Z0-9]{4}$/.test(seriesPart)) {\n    errors.push(`Serie en CAR inválida: ${seriesPart}`);\n  }\n  const correlativePart = car.slice(17, 27);\n  if (!/^[0-9]{10}$/.test(correlativePart)) {\n    errors.push(`Correlativo en CAR inválido: ${correlativePart}`);\n  }\n  return errors;\n}\n\nexport function parseSireCar(car: string): SireCarParsed {\n  const validationErrors = validateSireCar(car);\n  if (validationErrors.length > 0) {\n    throw new Error(`CAR inválido: ${validationErrors.join(\"; \")}`);\n  }\n  return {\n    issuerRuc: car.slice(0, 11),\n    cpeType: car.slice(11, 13),\n    series: car.slice(13, 17),\n    correlative: String(Number(car.slice(17, 27))),\n    rawCar: car,\n  };\n}\n",
  "src/modules/sire/duplicate-detector.ts": "/**\n * Detección y Prevención de Comprobantes Duplicados en SIRE (RVIE y RCE)\n * Criterio normativo SUNAT:\n * - RVIE: No puede existir más de un comprobante con el mismo emisor, tipo de CPE, serie, correlativo y período.\n * - RCE: No puede existir más de un comprobante con el mismo proveedor (RUC/Doc), tipo de CPE, serie, correlativo y período contable.\n */\n\nexport interface SireDuplicateCheckItem {\n  entityDocNumber: string; // RUC del emisor (RVIE) o proveedor (RCE)\n  cpeType: string;\n  series: string;\n  correlative: number | string;\n  period: string; // YYYY-MM o YYYYMM\n}\n\nexport function normalizeDuplicateKey(\n  entityDocNumber: string,\n  cpeType: string,\n  series: string,\n  correlative: number | string,\n  period: string\n): string {\n  const cleanEntity = entityDocNumber.trim();\n  const cleanType = cpeType.trim().padStart(2, \"0\").slice(-2);\n  const cleanSeries = series.trim().toUpperCase().padStart(4, \"0\").slice(-4);\n  const cleanCorrelative = String(correlative).replace(/\\D/g, \"\").padStart(8, \"0\");\n  const cleanPeriod = period.replace(/\\D/g, \"\").slice(0, 6); // YYYYMM\n  return `${cleanEntity}|${cleanType}|${cleanSeries}|${cleanCorrelative}|${cleanPeriod}`;\n}\n\nexport interface DuplicateDetectionResult {\n  hasDuplicates: boolean;\n  duplicates: string[];\n  uniqueCount: number;\n}\n\nexport function detectDuplicates<T extends SireDuplicateCheckItem>(\n  items: T[],\n  contextName: \"RVIE\" | \"RCE\"\n): DuplicateDetectionResult {\n  const seen = new Set<string>();\n  const duplicates: string[] = [];\n\n  for (const item of items) {\n    const key = normalizeDuplicateKey(\n      item.entityDocNumber,\n      item.cpeType,\n      item.series,\n      item.correlative,\n      item.period\n    );\n    if (seen.has(key)) {\n      duplicates.push(\n        `${contextName}: ${item.entityDocNumber} - tipo ${item.cpeType} ${item.series.toUpperCase()}-${item.correlative} (periodo ${item.period})`\n      );\n    } else {\n      seen.add(key);\n    }\n  }\n\n  return {\n    hasDuplicates: duplicates.length > 0,\n    duplicates,\n    uniqueCount: seen.size,\n  };\n}\n\nexport function assertNoDuplicates<T extends SireDuplicateCheckItem>(\n  items: T[],\n  contextName: \"RVIE\" | \"RCE\"\n): void {\n  const check = detectDuplicates(items, contextName);\n  if (check.hasDuplicates) {\n    throw new Error(\n      `Comprobante duplicado detectado en ${contextName}: ${check.duplicates.join(\"; \")}.`\n    );\n  }\n}\n",
  "src/modules/sire/rvie-generator.ts": "import { Decimal } from \"decimal.js\";\nimport JSZip from \"jszip\";\nimport { SireFileNameParams, SireRvieLineData, SireExportResult } from \"./types.js\";\nimport { buildSireCar } from \"./car-generator.js\";\nimport { assertNoDuplicates, normalizeDuplicateKey } from \"./duplicate-detector.js\";\n\nDecimal.set({ precision: 24, rounding: Decimal.ROUND_HALF_UP });\nconst ZERO = new Decimal(0);\n\nexport function buildSireFileName(params: SireFileNameParams): string {\n  const cleanRuc = params.ruc.padStart(11, \"0\").slice(-11);\n  const cleanYear = String(params.year).padStart(4, \"0\").slice(-4);\n  const cleanMonth = String(params.month).padStart(2, \"0\").slice(-2);\n  const opportunity = params.opportunityCode ?? \"02\";\n  const hasInfo = params.hasInformation !== false ? \"1\" : \"0\";\n  const hasContent = \"1\";\n  const currency = params.currencyIndicator ?? \"1\";\n  const generator = params.generatorIndicator ?? \"2\";\n  const ext = params.extension ?? \"txt\";\n\n  return `LE${cleanRuc}${cleanYear}${cleanMonth}00${params.bookCode}${opportunity}${hasInfo}${hasContent}${currency}${generator}.${ext}`;\n}\n\nexport function formatDateForSire(isoDate: string): string {\n  if (!isoDate) return \"\";\n  // If YYYY-MM-DD -> DD/MM/YYYY\n  const parts = isoDate.split(\"-\");\n  if (parts.length === 3) {\n    return `${parts[2].padStart(2, \"0\")}/${parts[1].padStart(2, \"0\")}/${parts[0]}`;\n  }\n  return isoDate;\n}\n\nexport function serializeRvieLine(data: SireRvieLineData): string {\n  const car = data.car || buildSireCar(data.companyRuc, data.cpeType, data.series, data.correlative);\n  const issueDateFormatted = formatDateForSire(data.issueDate);\n  const dueDateFormatted = data.dueDate ? formatDateForSire(data.dueDate) : \"\";\n  const modifiedDateFormatted = data.modifiedIssueDate ? formatDateForSire(data.modifiedIssueDate) : \"\";\n\n  const fields = [\n    data.companyRuc, // 1. RUC Emisor\n    data.companyName, // 2. Razón Social Emisor\n    data.period.replace(\"-\", \"\"), // 3. Período AAAAMM\n    car, // 4. CAR\n    issueDateFormatted, // 5. Fecha Emisión\n    dueDateFormatted, // 6. Fecha Vencimiento\n    data.cpeType, // 7. Tipo CPE\n    data.series, // 8. Serie\n    String(data.correlative).padStart(8, \"0\"), // 9. Correlativo\n    data.correlativeEnd ?? \"\", // 10. Correlativo Final\n    data.clientDocType, // 11. Tipo Doc Cliente\n    data.clientDocNumber, // 12. Num Doc Cliente\n    data.clientName, // 13. Razón Social Cliente\n    data.exportBase ?? \"0.00\", // 14. Exportación\n    data.taxableBase, // 15. Base Gravada\n    data.baseDiscount ?? \"0.00\", // 16. Descuento Base\n    data.igvAmount, // 17. IGV/IPM\n    data.igvDiscount ?? \"0.00\", // 18. Descuento IGV\n    data.exoneratedAmount ?? \"0.00\", // 19. Exonerado\n    data.inaffectedAmount ?? \"0.00\", // 20. Inafecto\n    data.iscAmount ?? \"0.00\", // 21. ISC\n    data.ivapBase ?? \"0.00\", // 22. Base IVAP\n    data.ivapAmount ?? \"0.00\", // 23. IVAP\n    data.icbperAmount ?? \"0.00\", // 24. ICBPER\n    data.otherTaxes ?? \"0.00\", // 25. Otros tributos\n    data.totalAmount, // 26. Total\n    data.currency, // 27. Moneda\n    data.currency === \"USD\" ? (data.exchangeRate ?? \"1.0000\") : \"\", // 28. Tipo Cambio\n    modifiedDateFormatted, // 29. Fecha Emi Doc Modificado\n    data.modifiedCpeType ?? \"\", // 30. Tipo Doc Modificado\n    data.modifiedSeries ?? \"\", // 31. Serie Doc Modificado\n    data.modifiedCorrelative ?? \"\", // 32. Correlativo Modificado\n    \"\", // 33. Identificación contrato\n    \"\", // 34. Error tipo 1\n    data.cancellationIndicator ?? \"1\", // 35. Indicador pago bancarizado\n    data.statusCode ?? \"1\", // 36. Estado (1: Válido)\n  ];\n\n  return fields.join(\"|\") + \"|\";\n}\n\nexport async function generateRvieExport(\n  companyRuc: string,\n  period: string, // \"YYYY-MM\"\n  lines: SireRvieLineData[],\n  options: { zip?: boolean } = {}\n): Promise<SireExportResult> {\n  // Validación estricta de duplicados en RVIE por emisor, serie, número y período\n  const rvieCheckItems = lines.map((l) => ({\n    entityDocNumber: l.companyRuc,\n    cpeType: l.cpeType,\n    series: l.series,\n    correlative: l.correlative,\n    period: l.period,\n  }));\n  assertNoDuplicates(rvieCheckItems, \"RVIE\");\n\n  const [year, month] = period.split(\"-\");\n  const hasInfo = lines.length > 0;\n\n  const txtLines = lines.map(serializeRvieLine);\n  const txtContent = txtLines.join(\"\\r\\n\") + (txtLines.length > 0 ? \"\\r\\n\" : \"\");\n\n  const fileName = buildSireFileName({\n    ruc: companyRuc,\n    year,\n    month,\n    bookCode: \"140400\",\n    hasInformation: hasInfo,\n    extension: \"txt\",\n  });\n\n  let zipFileName: string | undefined;\n  let zipBuffer: Uint8Array | undefined;\n\n  if (options.zip !== false) {\n    zipFileName = buildSireFileName({\n      ruc: companyRuc,\n      year,\n      month,\n      bookCode: \"140400\",\n      hasInformation: hasInfo,\n      extension: \"zip\",\n    });\n\n    const zip = new JSZip();\n    zip.file(fileName, txtContent);\n    zipBuffer = await zip.generateAsync({ type: \"uint8array\", compression: \"DEFLATE\" });\n  }\n\n  let totalBase = ZERO;\n  let totalIgv = ZERO;\n  let totalMonto = ZERO;\n\n  for (const l of lines) {\n    totalBase = totalBase.plus(l.taxableBase || 0);\n    totalIgv = totalIgv.plus(l.igvAmount || 0);\n    totalMonto = totalMonto.plus(l.totalAmount || 0);\n  }\n\n  return {\n    bookCode: \"140400\",\n    bookName: \"Registro de Ventas e Ingresos Electrónico (RVIE)\",\n    period,\n    fileName,\n    txtContent,\n    zipFileName,\n    zipBuffer,\n    lineCount: lines.length,\n    totalTaxableBase: totalBase.toFixed(2),\n    totalIgv: totalIgv.toFixed(2),\n    totalAmount: totalMonto.toFixed(2),\n  };\n}\n",
  "src/modules/sire/rce-generator.ts": "import { Decimal } from \"decimal.js\";\nimport JSZip from \"jszip\";\nimport { SireRceLineData, SireExportResult } from \"./types.js\";\nimport { buildSireFileName, formatDateForSire } from \"./rvie-generator.js\";\nimport { assertNoDuplicates } from \"./duplicate-detector.js\";\n\nDecimal.set({ precision: 24, rounding: Decimal.ROUND_HALF_UP });\nconst ZERO = new Decimal(0);\n\nexport function serializeRceLine(data: SireRceLineData): string {\n  const issueDateFormatted = formatDateForSire(data.issueDate);\n  const dueDateFormatted = data.dueDate ? formatDateForSire(data.dueDate) : \"\";\n  const modifiedDateFormatted = data.modifiedIssueDate ? formatDateForSire(data.modifiedIssueDate) : \"\";\n  const detractionDateFormatted = data.detractionDepositDate ? formatDateForSire(data.detractionDepositDate) : \"\";\n\n  const fields = [\n    data.companyRuc, // 1. RUC Adquirente\n    data.companyName, // 2. Razón Social Adquirente\n    data.period.replace(\"-\", \"\"), // 3. Período AAAAMM\n    data.car, // 4. CAR del emisor\n    issueDateFormatted, // 5. Fecha Emisión\n    dueDateFormatted, // 6. Fecha Vencimiento\n    data.cpeType, // 7. Tipo CPE\n    data.series, // 8. Serie\n    data.duaYear ?? \"\", // 9. Año DUA/DAM\n    String(data.correlative).padStart(8, \"0\"), // 10. Correlativo\n    data.correlativeEnd ?? \"\", // 11. Correlativo Final\n    data.supplierDocType, // 12. Tipo Doc Proveedor\n    data.supplierDocNumber, // 13. Num Doc Proveedor\n    data.supplierName, // 14. Razón Social Proveedor\n    data.baseGravadaExclusiva, // 15. Base Gravada Exclusiva\n    data.igvGravadoExclusivo, // 16. IGV Exclusivo\n    data.baseGravadaComun ?? \"0.00\", // 17. Base Común\n    data.igvGravadoComun ?? \"0.00\", // 18. IGV Común\n    data.baseGravadaSinCredito ?? \"0.00\", // 19. Base Sin Crédito\n    data.igvGravadoSinCredito ?? \"0.00\", // 20. IGV Sin Crédito\n    data.adquisicionesNoGravadas ?? \"0.00\", // 21. No Gravadas\n    data.iscAmount ?? \"0.00\", // 22. ISC\n    data.icbperAmount ?? \"0.00\", // 23. ICBPER\n    data.otherTaxes ?? \"0.00\", // 24. Otros tributos\n    data.totalAmount, // 25. Total\n    data.currency, // 26. Moneda\n    data.currency === \"USD\" ? (data.exchangeRate ?? \"1.0000\") : \"\", // 27. Tipo Cambio\n    modifiedDateFormatted, // 28. Fecha Emi Doc Modificado\n    data.modifiedCpeType ?? \"\", // 29. Tipo Doc Modificado\n    data.modifiedSeries ?? \"\", // 30. Serie Doc Modificado\n    data.modifiedCorrelative ?? \"\", // 31. Correlativo Doc Modificado\n    detractionDateFormatted, // 32. Fecha Detracción\n    data.detractionProofNumber ?? \"\", // 33. Constancia Detracción\n    data.retentionIndicator ?? \"\", // 34. Retención\n    data.classificationCode ?? \"1\", // 35. Clasificación Bienes/Servicios (1: Mercadería)\n    \"\", // 36. Contrato/Proyecto\n    \"\", // 37. Error 1\n    \"\", // 38. Error 2\n    \"\", // 39. Error 3\n    \"\", // 40. Error 4\n    data.bancarizadoIndicator ?? \"1\", // 41. Bancarización (1: Sí, 0: No)\n    data.statusCode ?? \"1\", // 42. Estado (1: En el período)\n  ];\n\n  return fields.join(\"|\") + \"|\";\n}\n\nexport async function generateRceExport(\n  companyRuc: string,\n  period: string, // \"YYYY-MM\"\n  lines: SireRceLineData[],\n  options: { zip?: boolean } = {}\n): Promise<SireExportResult> {\n  // Validación estricta de duplicados en RCE por proveedor, serie, número y período contable\n  const rceCheckItems = lines.map((l) => ({\n    entityDocNumber: l.supplierDocNumber,\n    cpeType: l.cpeType,\n    series: l.series,\n    correlative: l.correlative,\n    period: l.period,\n  }));\n  assertNoDuplicates(rceCheckItems, \"RCE\");\n\n  const [year, month] = period.split(\"-\");\n  const hasInfo = lines.length > 0;\n\n  const txtLines = lines.map(serializeRceLine);\n  const txtContent = txtLines.join(\"\\r\\n\") + (txtLines.length > 0 ? \"\\r\\n\" : \"\");\n\n  const fileName = buildSireFileName({\n    ruc: companyRuc,\n    year,\n    month,\n    bookCode: \"080400\",\n    hasInformation: hasInfo,\n    extension: \"txt\",\n  });\n\n  let zipFileName: string | undefined;\n  let zipBuffer: Uint8Array | undefined;\n\n  if (options.zip !== false) {\n    zipFileName = buildSireFileName({\n      ruc: companyRuc,\n      year,\n      month,\n      bookCode: \"080400\",\n      hasInformation: hasInfo,\n      extension: \"zip\",\n    });\n\n    const zip = new JSZip();\n    zip.file(fileName, txtContent);\n    zipBuffer = await zip.generateAsync({ type: \"uint8array\", compression: \"DEFLATE\" });\n  }\n\n  let totalBase = ZERO;\n  let totalIgv = ZERO;\n  let totalMonto = ZERO;\n\n  for (const l of lines) {\n    const baseExcl = new Decimal(l.baseGravadaExclusiva || 0);\n    const baseCom = new Decimal(l.baseGravadaComun || 0);\n    const igvExcl = new Decimal(l.igvGravadoExclusivo || 0);\n    const igvCom = new Decimal(l.igvGravadoComun || 0);\n\n    totalBase = totalBase.plus(baseExcl).plus(baseCom);\n    totalIgv = totalIgv.plus(igvExcl).plus(igvCom);\n    totalMonto = totalMonto.plus(l.totalAmount || 0);\n  }\n\n  return {\n    bookCode: \"080400\",\n    bookName: \"Registro de Compras Electrónico (RCE)\",\n    period,\n    fileName,\n    txtContent,\n    zipFileName,\n    zipBuffer,\n    lineCount: lines.length,\n    totalTaxableBase: totalBase.toFixed(2),\n    totalIgv: totalIgv.toFixed(2),\n    totalAmount: totalMonto.toFixed(2),\n  };\n}\n",
  "src/modules/sire/sire-orchestrator.ts": "import { Decimal } from \"decimal.js\";\nimport {\n  SireRvieLineData,\n  SireRceLineData,\n  SireExportResult,\n  SireProposalAction,\n  SireSettlementIntegrationPayload,\n  SireCpeInput,\n} from \"./types.js\";\nimport { generateRvieExport } from \"./rvie-generator.js\";\nimport { generateRceExport } from \"./rce-generator.js\";\nimport { detectDuplicates, DuplicateDetectionResult } from \"./duplicate-detector.js\";\nimport { buildSireCar } from \"./car-generator.js\";\nimport { PurchaseService } from \"../purchases/purchase-service.js\";\nimport { PurchaseDocumentRecord } from \"../purchases/types.js\";\n\nimport { CompanyProfile } from \"../../core/tax-engine/types.js\";\n\nDecimal.set({ precision: 24, rounding: Decimal.ROUND_HALF_UP });\nconst ZERO = new Decimal(0);\nconst round = (val: Decimal) => val.toDecimalPlaces(2, Decimal.ROUND_HALF_UP);\n\nexport interface SireProposalComparison {\n  matchedCars: string[];\n  missingInSunat: string[]; // Documentos locales para COMPLEMENTAR o REEMPLAZAR\n  missingInLocal: string[]; // Documentos que SUNAT propone pero no tenemos en compras\n  recommendedAction: SireProposalAction;\n}\n\nexport class SireOrchestrator {\n  constructor(private purchaseService: PurchaseService) {}\n\n  /**\n   * Mapea un comprobante emitido (CPE) a la línea oficial de RVIE (Libro 14.4)\n   */\n  public mapCpeToRvieLine(\n    cpe: SireCpeInput,\n    company: CompanyProfile,\n    period: string\n  ): SireRvieLineData {\n    const car = buildSireCar(company.ruc, cpe.cpeType, cpe.series, cpe.correlative);\n\n    return {\n      companyRuc: company.ruc,\n      companyName: company.legalName,\n      period,\n      car,\n      issueDate: cpe.issueDate,\n      cpeType: cpe.cpeType,\n      series: cpe.series,\n      correlative: String(cpe.correlative),\n      clientDocType: cpe.clientDocType,\n      clientDocNumber: cpe.clientDocNumber,\n      clientName: cpe.clientName,\n      taxableBase: cpe.taxableBase,\n      igvAmount: cpe.igvAmount,\n      totalAmount: cpe.totalAmount,\n      currency: cpe.currency,\n      exchangeRate: cpe.exchangeRate,\n      statusCode: cpe.status === \"DE_BAJA\" ? \"2\" : \"1\",\n    };\n  }\n\n  /**\n   * Mapea un registro de compra al formato reglamentario de RCE (Libro 8.4)\n   */\n  public mapPurchaseToRceLine(purchase: PurchaseDocumentRecord): SireRceLineData {\n    return {\n      companyRuc: purchase.companyRuc,\n      companyName: purchase.supplier.name,\n      period: purchase.accountingPeriod,\n      car: purchase.car,\n      issueDate: purchase.issueDate,\n      dueDate: purchase.dueDate,\n      cpeType: purchase.docType,\n      series: purchase.series,\n      correlative: purchase.correlative,\n      supplierDocType: purchase.supplier.docType,\n      supplierDocNumber: purchase.supplier.docNumber,\n      supplierName: purchase.supplier.name,\n      baseGravadaExclusiva: purchase.canUseFiscalCredit ? purchase.totals.baseGravadaExclusiva : \"0.00\",\n      igvGravadoExclusivo: purchase.canUseFiscalCredit ? purchase.totals.igvGravadoExclusivo : \"0.00\",\n      baseGravadaComun: purchase.canUseFiscalCredit ? purchase.totals.baseGravadaComun : \"0.00\",\n      igvGravadoComun: purchase.canUseFiscalCredit ? purchase.totals.igvGravadoComun : \"0.00\",\n      baseGravadaSinCredito: purchase.canUseFiscalCredit ? purchase.totals.baseGravadaSinCredito : purchase.totals.baseGravadaExclusiva,\n      igvGravadoSinCredito: purchase.canUseFiscalCredit ? purchase.totals.igvGravadoSinCredito : purchase.totals.igvGravadoExclusivo,\n      adquisicionesNoGravadas: purchase.totals.adquisicionesNoGravadas,\n      totalAmount: purchase.totals.totalAdquisicion,\n      currency: purchase.currency,\n      exchangeRate: purchase.exchangeRate,\n      detractionDepositDate: purchase.detraction?.depositDate,\n      detractionProofNumber: purchase.detraction?.depositProofNumber,\n      classificationCode: \"1\",\n      bancarizadoIndicator: purchase.isBancarizado ? \"1\" : \"0\",\n      statusCode: \"1\",\n    };\n  }\n\n  /**\n   * Genera el libro RVIE (Ventas) a partir de los CPE emitidos\n   */\n\n  /**\n   * Verifica preventivamente si existen comprobantes duplicados en la lista de ventas para RVIE\n   */\n  public checkRvieDuplicates(\n    cpeList: SireCpeInput[],\n    period: string\n  ): DuplicateDetectionResult {\n    const items = cpeList.map((c) => ({\n      entityDocNumber: c.companyRuc,\n      cpeType: c.cpeType,\n      series: c.series,\n      correlative: c.correlative,\n      period,\n    }));\n    return detectDuplicates(items, \"RVIE\");\n  }\n\n  /**\n   * Verifica preventivamente si existen comprobantes duplicados en las compras registradas para RCE\n   */\n  public checkRceDuplicates(\n    period: string,\n    companyRuc?: string\n  ): DuplicateDetectionResult {\n    const purchases = this.purchaseService.listByPeriod(period, companyRuc);\n    const items = purchases.map((p) => ({\n      entityDocNumber: p.supplier.docNumber,\n      cpeType: p.docType,\n      series: p.series,\n      correlative: p.correlative,\n      period: p.accountingPeriod,\n    }));\n    return detectDuplicates(items, \"RCE\");\n  }\n\n  public async generateRvieBook(\n    company: CompanyProfile,\n    period: string, // \"YYYY-MM\"\n    cpeList: SireCpeInput[],\n    options: { zip?: boolean } = {}\n  ): Promise<SireExportResult> {\n    const validCpes = cpeList.filter((c) => c.status !== \"RECHAZADO\" && c.status !== \"BORRADOR\");\n    const lines = validCpes.map((c) => this.mapCpeToRvieLine(c, company, period));\n    return generateRvieExport(company.ruc, period, lines, options);\n  }\n\n  /**\n   * Genera el libro RCE (Compras) a partir del registro de compras del período\n   */\n  public async generateRceBook(\n    companyRuc: string,\n    period: string, // \"YYYY-MM\"\n    options: { zip?: boolean } = {}\n  ): Promise<SireExportResult> {\n    const purchases = this.purchaseService.listByPeriod(period, companyRuc).filter(\n      (p) => p.sireStatus !== \"EXCLUIDO\"\n    );\n    const lines = purchases.map((p) => this.mapPurchaseToRceLine(p));\n    return generateRceExport(companyRuc, period, lines, options);\n  }\n\n  /**\n   * Concilia la propuesta de compras emitida por SUNAT con las compras registradas internamente\n   */\n  public compareProposalWithPurchases(\n    sunatProposalCars: string[],\n    period: string,\n    companyRuc: string\n  ): SireProposalComparison {\n    const localPurchases = this.purchaseService.listByPeriod(period, companyRuc);\n    const localCars = new Set(localPurchases.map((p) => p.car));\n    const sunatCarSet = new Set(sunatProposalCars);\n\n    const matchedCars: string[] = [];\n    const missingInSunat: string[] = [];\n    const missingInLocal: string[] = [];\n\n    for (const car of sunatProposalCars) {\n      if (localCars.has(car)) {\n        matchedCars.push(car);\n      } else {\n        missingInLocal.push(car);\n      }\n    }\n\n    for (const p of localPurchases) {\n      if (!sunatCarSet.has(p.car)) {\n        missingInSunat.push(p.car);\n      }\n    }\n\n    let recommendedAction: SireProposalAction = \"ACEPTAR\";\n    if (missingInSunat.length > 0 && missingInLocal.length === 0) {\n      recommendedAction = \"COMPLEMENTAR\";\n    } else if (missingInSunat.length > 0 || missingInLocal.length > 0) {\n      recommendedAction = \"REEMPLAZAR\";\n    }\n\n    return {\n      matchedCars,\n      missingInSunat,\n      missingInLocal,\n      recommendedAction,\n    };\n  }\n\n  /**\n   * Prepara los totales consolidados de Compras y Ventas para la Preliquidación Mensual del PDT 621\n   */\n  public getSettlementIntegrationPayload(\n    period: string,\n    companyRuc: string,\n    cpeList: SireCpeInput[]\n  ): SireSettlementIntegrationPayload {\n    // 1. Totales de Ventas (RVIE)\n    let salesBase = ZERO;\n    let salesIgv = ZERO;\n    let salesCount = 0;\n\n    for (const cpe of cpeList) {\n      if (cpe.status === \"ACEPTADO\" || cpe.status === \"ACEPTADO_CON_OBSERVACIONES\") {\n        salesBase = salesBase.plus(cpe.taxableBase || 0);\n        salesIgv = salesIgv.plus(cpe.igvAmount || 0);\n        salesCount++;\n      }\n    }\n\n    // 2. Totales de Compras (RCE)\n    const purchaseSummary = this.purchaseService.getMonthlySummary(period, companyRuc);\n\n    return {\n      period,\n      salesTaxableBase: round(salesBase).toFixed(2),\n      salesIgv: round(salesIgv).toFixed(2),\n      purchasesTaxableBase: purchaseSummary.baseGravadaExclusivaTotal,\n      purchasesIgv: purchaseSummary.totalCreditoFiscalAceptado,\n      purchasesCount: purchaseSummary.totalDocuments,\n      salesCount,\n    };\n  }\n}\n",
  "src/modules/sire/index.ts": "export * from './types.js';\nexport * from './car-generator.js';\nexport * from './duplicate-detector.js';\nexport * from './rvie-generator.js';\nexport * from './rce-generator.js';\nexport * from './sire-orchestrator.js';\n",
  "src/modules/__tests__/purchases.test.ts": "import { describe, expect, it, beforeEach } from \"vitest\";\nimport { PurchaseService } from \"../purchases/purchase-service.js\";\nimport { PurchaseDocumentInput } from \"../purchases/types.js\";\n\ndescribe(\"Módulo de Compras (Gestión y Control de Crédito Fiscal)\", () => {\n  let purchaseService: PurchaseService;\n\n  beforeEach(() => {\n    purchaseService = new PurchaseService();\n  });\n\n  const baseSupplier = {\n    docType: \"6\" as const,\n    docNumber: \"20123456786\", // RUC válido\n    name: \"DISTRIBUIDORA MAYORISTA S.A.C.\",\n  };\n\n  const validPurchaseInput: PurchaseDocumentInput = {\n    companyRuc: \"10445533811\",\n    supplier: baseSupplier,\n    docType: \"01\",\n    series: \"F001\",\n    correlative: 1234,\n    issueDate: \"2026-03-10\",\n    accountingPeriod: \"2026-03\",\n    currency: \"PEN\",\n    paymentMethod: \"CONTADO\",\n    isBancarizado: true,\n    items: [\n      {\n        description: \"Mercadería para reventa\",\n        quantity: 10,\n        unitValue: \"100.00\",\n        taxDestination: \"GRAVADO_EXCLUSIVO\",\n        classification: \"1\",\n      },\n    ],\n  };\n\n  it(\"1. registra una compra válida y calcula el crédito fiscal al 100%\", () => {\n    const record = purchaseService.registerPurchase(validPurchaseInput);\n\n    expect(record.car).toBe(\"2012345678601F0010000001234\");\n    expect(record.fullNumber).toBe(\"F001-00001234\");\n    expect(record.totals.baseGravadaExclusiva).toBe(\"1000.00\");\n    expect(record.totals.igvGravadoExclusivo).toBe(\"180.00\");\n    expect(record.totals.totalAdquisicion).toBe(\"1180.00\");\n    expect(record.canUseFiscalCredit).toBe(true);\n    expect(record.totals.totalCreditoFiscal).toBe(\"180.00\");\n  });\n\n  it(\"2. restringe el crédito fiscal si el comprobante excede el plazo legal de 12 meses\", () => {\n    const oldPurchase: PurchaseDocumentInput = {\n      ...validPurchaseInput,\n      series: \"F002\",\n      correlative: 55,\n      issueDate: \"2024-12-01\", // 15 meses antes de 2026-03\n      accountingPeriod: \"2026-03\",\n    };\n\n    const record = purchaseService.registerPurchase(oldPurchase);\n\n    expect(record.canUseFiscalCredit).toBe(false);\n    expect(record.totals.totalCreditoFiscal).toBe(\"0.00\");\n    expect(record.fiscalCreditRestrictionReason).toMatch(/12 meses/);\n  });\n\n  it(\"3. restringe el crédito fiscal por falta de bancarización en compras >= S/ 2,000\", () => {\n    const bigPurchaseNoBank: PurchaseDocumentInput = {\n      ...validPurchaseInput,\n      series: \"F003\",\n      correlative: 99,\n      isBancarizado: false,\n      items: [\n        {\n          description: \"Lote grande de insumos\",\n          quantity: 25,\n          unitValue: \"100.00\", // Base: 2500, IGV: 450, Total: 2950 >= 2000\n          taxDestination: \"GRAVADO_EXCLUSIVO\",\n        },\n      ],\n    };\n\n    const record = purchaseService.registerPurchase(bigPurchaseNoBank);\n\n    expect(record.canUseFiscalCredit).toBe(false);\n    expect(record.totals.totalCreditoFiscal).toBe(\"0.00\");\n    expect(record.fiscalCreditRestrictionReason).toMatch(/bancarización/i);\n  });\n\n  it(\"4. suspende el crédito fiscal si la compra está sujeta a detracción (SPOT) sin constancia\", () => {\n    const detractionPurchase: PurchaseDocumentInput = {\n      ...validPurchaseInput,\n      series: \"F004\",\n      correlative: 88,\n      detraction: {\n        hasDetraction: true,\n        detractionCode: \"022\", // Otros servicios empresariales\n        detractionPercentage: 12,\n        // Sin depósito de detracción aún\n      },\n    };\n\n    const record = purchaseService.registerPurchase(detractionPurchase);\n\n    expect(record.canUseFiscalCredit).toBe(false);\n    expect(record.fiscalCreditRestrictionReason).toMatch(/SPOT/i);\n  });\n\n  it(\"5. una boleta de venta (03) recibida no genera derecho a crédito fiscal\", () => {\n    const boletaPurchase: PurchaseDocumentInput = {\n      ...validPurchaseInput,\n      docType: \"03\",\n      series: \"B001\",\n      correlative: 450,\n    };\n\n    const record = purchaseService.registerPurchase(boletaPurchase);\n\n    expect(record.canUseFiscalCredit).toBe(false);\n    expect(record.totals.totalCreditoFiscal).toBe(\"0.00\");\n    expect(record.fiscalCreditRestrictionReason).toMatch(/boletas de venta/i);\n  });\n\n  it(\"6. evita registrar compras duplicadas con el mismo CAR\", () => {\n    purchaseService.registerPurchase(validPurchaseInput);\n\n    expect(() => purchaseService.registerPurchase(validPurchaseInput)).toThrow(/ya está registrado/);\n  });\n\n  it(\"7. genera el resumen mensual excluyendo comprobantes marcados como EXCLUIDO\", () => {\n    const doc1 = purchaseService.registerPurchase(validPurchaseInput);\n    const doc2 = purchaseService.registerPurchase({\n      ...validPurchaseInput,\n      series: \"F005\",\n      correlative: 10,\n      items: [\n        {\n          description: \"Segundo ítem\",\n          quantity: 5,\n          unitValue: \"100.00\", // Base: 500, IGV: 90\n          taxDestination: \"GRAVADO_EXCLUSIVO\",\n        },\n      ],\n    });\n\n    // Excluir doc2 de la propuesta\n    purchaseService.updateSireStatus(doc2.car, \"EXCLUIDO\");\n\n    const summary = purchaseService.getMonthlySummary(\"2026-03\", \"10445533811\");\n\n    expect(summary.totalDocuments).toBe(1);\n    expect(summary.baseGravadaExclusivaTotal).toBe(\"1000.00\");\n    expect(summary.igvGravadoExclusivoTotal).toBe(\"180.00\");\n    expect(summary.totalCreditoFiscalAceptado).toBe(\"180.00\");\n  });\n});\n",
  "src/modules/__tests__/sire.test.ts": "import { describe, expect, it, beforeEach } from \"vitest\";\nimport JSZip from \"jszip\";\nimport { SireOrchestrator } from \"../sire/sire-orchestrator.js\";\nimport { buildSireCar, parseSireCar, validateSireCar } from \"../sire/car-generator.js\";\nimport { buildSireFileName } from \"../sire/rvie-generator.js\";\nimport { PurchaseService } from \"../purchases/purchase-service.js\";\nimport { calculateMonthlySettlement } from \"../../core/tax-engine/monthly-settlement.js\";\nimport { SireCpeInput } from \"../sire/types.js\";\nimport { CompanyProfile } from \"../../core/tax-engine/types.js\";\n\ndescribe(\"Módulo SIRE: Sistema Integrado de Registros Electrónicos (RVIE / RCE)\", () => {\n  let purchaseService: PurchaseService;\n  let sireOrchestrator: SireOrchestrator;\n\n  beforeEach(() => {\n    purchaseService = new PurchaseService();\n    sireOrchestrator = new SireOrchestrator(purchaseService);\n  });\n\n  const testCompany: CompanyProfile = {\n    ruc: \"10445533811\",\n    legalName: \"JOSE BARRIENTOS\",\n    taxRegime: \"RMT\",\n    address: {\n      ubigeo: \"150101\",\n      department: \"Lima\",\n      province: \"Lima\",\n      district: \"Lima\",\n      addressLine: \"Av. Principal 123\",\n    },\n  };\n\n  describe(\"1. Generador y Validador del Código de Anotación de Registro (CAR)\", () => {\n    it(\"genera un CAR determinista de exactamente 27 caracteres\", () => {\n      const car = buildSireCar(\"20123456786\", \"01\", \"F001\", 123);\n      expect(car).toHaveLength(27);\n      expect(car).toBe(\"2012345678601F0010000000123\");\n\n      const errors = validateSireCar(car);\n      expect(errors).toHaveLength(0);\n    });\n\n    it(\"parsea correctamente los componentes del CAR\", () => {\n      const car = \"2012345678601F0010000000123\";\n      const parsed = parseSireCar(car);\n\n      expect(parsed.issuerRuc).toBe(\"20123456786\");\n      expect(parsed.cpeType).toBe(\"01\");\n      expect(parsed.series).toBe(\"F001\");\n      expect(parsed.correlative).toBe(\"123\");\n    });\n\n    it(\"detecta errores cuando el CAR tiene longitud o formato inválido\", () => {\n      const errors = validateSireCar(\"CAR_CORTO_INVALIDO\");\n      expect(errors.length).toBeGreaterThan(0);\n      expect(errors[0]).toMatch(/27 caracteres/);\n    });\n  });\n\n  describe(\"2. Nomenclatura oficial de Archivos SIRE\", () => {\n    it(\"genera el nombre reglamentario SUNAT para RVIE (Libro 140400)\", () => {\n      const fileName = buildSireFileName({\n        ruc: \"10445533811\",\n        year: 2026,\n        month: \"03\",\n        bookCode: \"140400\",\n        extension: \"txt\",\n      });\n\n      expect(fileName).toBe(\"LE1044553381120260300140400021112.txt\");\n    });\n\n    it(\"genera el nombre reglamentario SUNAT para RCE (Libro 080400)\", () => {\n      const fileName = buildSireFileName({\n        ruc: \"10445533811\",\n        year: 2026,\n        month: \"03\",\n        bookCode: \"080400\",\n        extension: \"zip\",\n      });\n\n      expect(fileName).toBe(\"LE1044553381120260300080400021112.zip\");\n    });\n  });\n\n  describe(\"3. RVIE (Registro de Ventas e Ingresos Electrónico)\", () => {\n    it(\"genera el libro RVIE con tramas delimitadas por pipe y empaquetado ZIP\", async () => {\n      const cpeList: SireCpeInput[] = [\n        {\n          id: \"cpe-1\",\n          companyId: \"comp-1\",\n          companyRuc: \"10445533811\",\n          cpeType: \"01\",\n          series: \"F001\",\n          correlative: 1,\n          fullNumber: \"F001-00000001\",\n          issueDate: \"2026-03-05\",\n          currency: \"PEN\",\n          clientDocType: \"6\",\n          clientDocNumber: \"20123456786\",\n          clientName: \"CLIENTE VIP S.A.C.\",\n          taxableBase: \"2000.00\",\n          igvAmount: \"360.00\",\n          totalAmount: \"2360.00\",\n          status: \"ACEPTADO\",\n          createdAt: new Date().toISOString(),\n          updatedAt: new Date().toISOString(),\n        },\n      ];\n\n      const result = await sireOrchestrator.generateRvieBook(testCompany, \"2026-03\", cpeList, { zip: true });\n\n      expect(result.bookCode).toBe(\"140400\");\n      expect(result.lineCount).toBe(1);\n      expect(result.totalTaxableBase).toBe(\"2000.00\");\n      expect(result.totalIgv).toBe(\"360.00\");\n      expect(result.totalAmount).toBe(\"2360.00\");\n\n      // Validar delimitadores pipe |\n      expect(result.txtContent).toContain(\"10445533811|JOSE BARRIENTOS|202603|\");\n      expect(result.txtContent).toContain(\"|2000.00|0.00|360.00|\");\n\n      // Validar ZIP generado\n      expect(result.zipFileName).toBe(\"LE1044553381120260300140400021112.zip\");\n      expect(result.zipBuffer).toBeDefined();\n\n      const zip = await JSZip.loadAsync(result.zipBuffer!);\n      const filesInZip = Object.keys(zip.files);\n      expect(filesInZip).toContain(result.fileName);\n    });\n  });\n\n  describe(\"4. RCE (Registro de Compras Electrónico)\", () => {\n    it(\"genera el libro RCE a partir de las compras registradas con 42 campos reglamentarios\", async () => {\n      purchaseService.registerPurchase({\n        companyRuc: \"10445533811\",\n        supplier: {\n          docType: \"6\",\n          docNumber: \"20123456786\",\n          name: \"PROVEEDOR CENTRAL S.A.C.\",\n        },\n        docType: \"01\",\n        series: \"F001\",\n        correlative: 890,\n        issueDate: \"2026-03-12\",\n        accountingPeriod: \"2026-03\",\n        currency: \"PEN\",\n        paymentMethod: \"CONTADO\",\n        isBancarizado: true,\n        items: [\n          {\n            description: \"Servidor local y equipos\",\n            quantity: 1,\n            unitValue: \"5000.00\",\n            taxDestination: \"GRAVADO_EXCLUSIVO\",\n            classification: \"2\", // Activo fijo\n          },\n        ],\n      });\n\n      const result = await sireOrchestrator.generateRceBook(\"10445533811\", \"2026-03\", { zip: true });\n\n      expect(result.bookCode).toBe(\"080400\");\n      expect(result.lineCount).toBe(1);\n      expect(result.totalTaxableBase).toBe(\"5000.00\");\n      expect(result.totalIgv).toBe(\"900.00\");\n      expect(result.totalAmount).toBe(\"5900.00\");\n\n      const line = result.txtContent.trim().split(\"\\r\\n\")[0];\n      const fields = line.split(\"|\");\n      // Debe contener al menos 42 campos reglamentarios\n      expect(fields.length).toBeGreaterThanOrEqual(42);\n      expect(fields[0]).toBe(\"10445533811\");\n      expect(fields[3]).toBe(\"2012345678601F0010000000890\"); // CAR\n      expect(fields[14]).toBe(\"5000.00\"); // Base gravada exclusiva\n      expect(fields[15]).toBe(\"900.00\"); // IGV exclusivo\n    });\n  });\n\n  describe(\"5. Conciliación y Acciones sobre la Propuesta SUNAT\", () => {\n    it(\"recomienda ACEPTAR cuando la propuesta de SUNAT coincide exactamente con los registros locales\", () => {\n      const reg = purchaseService.registerPurchase({\n        companyRuc: \"10445533811\",\n        supplier: {\n          docType: \"6\",\n          docNumber: \"20123456786\",\n          name: \"PROVEEDOR 1 S.A.\",\n        },\n        docType: \"01\",\n        series: \"F001\",\n        correlative: 100,\n        issueDate: \"2026-03-15\",\n        accountingPeriod: \"2026-03\",\n        currency: \"PEN\",\n        paymentMethod: \"CONTADO\",\n        isBancarizado: true,\n        items: [\n          {\n            description: \"Item\",\n            quantity: 1,\n            unitValue: \"100.00\",\n            taxDestination: \"GRAVADO_EXCLUSIVO\",\n          },\n        ],\n      });\n\n      const comparison = sireOrchestrator.compareProposalWithPurchases([reg.car], \"2026-03\", \"10445533811\");\n\n      expect(comparison.recommendedAction).toBe(\"ACEPTAR\");\n      expect(comparison.matchedCars).toHaveLength(1);\n      expect(comparison.missingInSunat).toHaveLength(0);\n      expect(comparison.missingInLocal).toHaveLength(0);\n    });\n\n    it(\"recomienda COMPLEMENTAR cuando hay compras locales que SUNAT no incluyó en su propuesta\", () => {\n      const reg = purchaseService.registerPurchase({\n        companyRuc: \"10445533811\",\n        supplier: {\n          docType: \"6\",\n          docNumber: \"20123456786\",\n          name: \"PROVEEDOR 2 S.A.\",\n        },\n        docType: \"01\",\n        series: \"F002\",\n        correlative: 200,\n        issueDate: \"2026-03-16\",\n        accountingPeriod: \"2026-03\",\n        currency: \"PEN\",\n        paymentMethod: \"CONTADO\",\n        isBancarizado: true,\n        items: [\n          {\n            description: \"Item 2\",\n            quantity: 1,\n            unitValue: \"200.00\",\n            taxDestination: \"GRAVADO_EXCLUSIVO\",\n          },\n        ],\n      });\n\n      // SUNAT propone lista vacía\n      const comparison = sireOrchestrator.compareProposalWithPurchases([], \"2026-03\", \"10445533811\");\n\n      expect(comparison.recommendedAction).toBe(\"COMPLEMENTAR\");\n      expect(comparison.missingInSunat).toContain(reg.car);\n    });\n  });\n\n  describe(\"6. Integración con el Motor Contable y Preliquidación PDT 621\", () => {\n    it(\"alimenta automáticamente los totales a la Preliquidación Mensual del IGV y Renta\", () => {\n      // 1. Registrar ventas emitidas\n      const cpeList: SireCpeInput[] = [\n        {\n          id: \"cpe-v1\",\n          companyId: \"comp-1\",\n          companyRuc: \"10445533811\",\n          cpeType: \"01\",\n          series: \"F001\",\n          correlative: 10,\n          fullNumber: \"F001-00000010\",\n          issueDate: \"2026-03-15\",\n          currency: \"PEN\",\n          clientDocType: \"6\",\n          clientDocNumber: \"20123456786\",\n          clientName: \"CLIENTE S.A.C.\",\n          taxableBase: \"10000.00\",\n          igvAmount: \"1800.00\",\n          totalAmount: \"11800.00\",\n          status: \"ACEPTADO\",\n          createdAt: new Date().toISOString(),\n          updatedAt: new Date().toISOString(),\n        },\n      ];\n\n      // 2. Registrar compras aceptadas\n      purchaseService.registerPurchase({\n        companyRuc: \"10445533811\",\n        supplier: {\n          docType: \"6\",\n          docNumber: \"20123456786\",\n          name: \"PROVEEDOR S.A.C.\",\n        },\n        docType: \"01\",\n        series: \"F001\",\n        correlative: 50,\n        issueDate: \"2026-03-18\",\n        accountingPeriod: \"2026-03\",\n        currency: \"PEN\",\n        paymentMethod: \"CONTADO\",\n        isBancarizado: true,\n        items: [\n          {\n            description: \"Mercaderías\",\n            quantity: 1,\n            unitValue: \"4000.00\",\n            taxDestination: \"GRAVADO_EXCLUSIVO\",\n          },\n        ],\n      });\n\n      // 3. Extraer payload integrado desde SIRE\n      const payload = sireOrchestrator.getSettlementIntegrationPayload(\"2026-03\", \"10445533811\", cpeList);\n\n      expect(payload.salesTaxableBase).toBe(\"10000.00\");\n      expect(payload.salesIgv).toBe(\"1800.00\");\n      expect(payload.purchasesTaxableBase).toBe(\"4000.00\");\n      expect(payload.purchasesIgv).toBe(\"720.00\"); // 4000 * 18%\n\n      // 4. Ejecutar preliquidación tributaria\n      const settlement = calculateMonthlySettlement({\n        period: \"2026-03\",\n        regime: \"RMT\",\n        accumulatedNetRevenueBeforePeriod: \"0\",\n        salesTaxableBase: payload.salesTaxableBase,\n        salesIgv: payload.salesIgv,\n        purchasesTaxableBase: payload.purchasesTaxableBase,\n        purchasesIgv: payload.purchasesIgv,\n      });\n\n      // Débito fiscal (1800) - Crédito fiscal (720) = IGV a pagar (1080)\n      expect(settlement.debitoFiscalIgv).toBe(\"1800.00\");\n      expect(settlement.creditoFiscalIgv).toBe(\"720.00\");\n      expect(settlement.igvPagar).toBe(\"1080.00\");\n      expect(settlement.rentaPagar).toBe(\"100.00\"); // 1% de 10,000 en RMT <= 300 UIT\n      expect(settlement.totalTributosAPagar).toBe(\"1180.00\");\n    });\n  });\n});\n",
  "src/modules/__tests__/sire-duplicates.test.ts": "import { describe, expect, it, beforeEach } from \"vitest\";\nimport { PurchaseService } from \"../purchases/purchase-service.js\";\nimport { PurchaseDocumentInput } from \"../purchases/types.js\";\nimport { SireOrchestrator } from \"../sire/sire-orchestrator.js\";\nimport { generateRvieExport } from \"../sire/rvie-generator.js\";\nimport { generateRceExport } from \"../sire/rce-generator.js\";\nimport {\n  detectDuplicates,\n  normalizeDuplicateKey,\n  assertNoDuplicates,\n} from \"../sire/duplicate-detector.js\";\nimport { SireRvieLineData, SireRceLineData, SireCpeInput } from \"../sire/types.js\";\nimport { CompanyProfile } from \"../../core/tax-engine/types.js\";\n\ndescribe(\"Detección y Prevención de Comprobantes Duplicados en RVIE y RCE\", () => {\n  let purchaseService: PurchaseService;\n  let sireOrchestrator: SireOrchestrator;\n\n  beforeEach(() => {\n    purchaseService = new PurchaseService();\n    sireOrchestrator = new SireOrchestrator(purchaseService);\n  });\n\n  const company: CompanyProfile = {\n    ruc: \"10445533811\",\n    legalName: \"JOSE BARRIENTOS\",\n    taxRegime: \"RMT\",\n    address: {\n      ubigeo: \"150101\",\n      department: \"Lima\",\n      province: \"Lima\",\n      district: \"Lima\",\n      addressLine: \"Av. Principal 123\",\n    },\n  };\n\n  const supplierA = {\n    docType: \"6\" as const,\n    docNumber: \"20123456786\", // RUC con dígito verificador válido\n    name: \"PROVEEDOR ALFA S.A.C.\",\n  };\n\n  const supplierB = {\n    docType: \"6\" as const,\n    docNumber: \"20600000005\", // RUC con dígito verificador válido\n    name: \"PROVEEDOR BETA S.A.C.\",\n  };\n\n  const basePurchase: PurchaseDocumentInput = {\n    companyRuc: \"10445533811\",\n    supplier: supplierA,\n    docType: \"01\",\n    series: \"F001\",\n    correlative: 100,\n    issueDate: \"2026-03-10\",\n    accountingPeriod: \"2026-03\",\n    currency: \"PEN\",\n    paymentMethod: \"CONTADO\",\n    isBancarizado: true,\n    items: [\n      {\n        description: \"Bienes comerciales\",\n        quantity: 1,\n        unitValue: \"500.00\",\n        taxDestination: \"GRAVADO_EXCLUSIVO\",\n      },\n    ],\n  };\n\n  describe(\"1. Detección en Compras y RCE (Registro de Compras)\", () => {\n    it(\"evita registrar dos veces el mismo comprobante del mismo proveedor, serie, número y período\", () => {\n      purchaseService.registerPurchase(basePurchase);\n\n      expect(\n        purchaseService.hasPurchase(\"20123456786\", \"01\", \"F001\", 100, \"2026-03\")\n      ).toBe(true);\n\n      // Intento de registrar el duplicado\n      expect(() => purchaseService.registerPurchase(basePurchase)).toThrow(\n        /ya está registrado para el proveedor 20123456786 en el periodo 2026-03/\n      );\n    });\n\n    it(\"permite registrar comprobantes con la misma serie y número si pertenecen a PROVEEDORES DISTINTOS\", () => {\n      const purchaseProvA = purchaseService.registerPurchase({\n        ...basePurchase,\n        supplier: supplierA,\n        series: \"F001\",\n        correlative: 555,\n      });\n\n      const purchaseProvB = purchaseService.registerPurchase({\n        ...basePurchase,\n        supplier: supplierB,\n        series: \"F001\",\n        correlative: 555,\n      });\n\n      expect(purchaseProvA.car).not.toBe(purchaseProvB.car);\n      expect(purchaseProvA.supplier.docNumber).toBe(\"20123456786\");\n      expect(purchaseProvB.supplier.docNumber).toBe(\"20600000005\");\n    });\n\n    it(\"permite registrar comprobantes del mismo proveedor con distinta serie o número correlativo\", () => {\n      purchaseService.registerPurchase({\n        ...basePurchase,\n        series: \"F001\",\n        correlative: 1,\n      });\n\n      const secondDoc = purchaseService.registerPurchase({\n        ...basePurchase,\n        series: \"F001\",\n        correlative: 2,\n      });\n\n      const thirdDoc = purchaseService.registerPurchase({\n        ...basePurchase,\n        series: \"F002\",\n        correlative: 1,\n      });\n\n      expect(secondDoc.correlative).toBe(\"00000002\");\n      expect(thirdDoc.series).toBe(\"F002\");\n    });\n\n    it(\"generateRceExport rechaza tramas que contengan comprobantes repetidos de un mismo proveedor\", async () => {\n      const line: SireRceLineData = {\n        companyRuc: \"10445533811\",\n        companyName: \"JOSE BARRIENTOS\",\n        period: \"202603\",\n        car: \"2012345678601F0010000000100\",\n        issueDate: \"10/03/2026\",\n        cpeType: \"01\",\n        series: \"F001\",\n        correlative: \"100\",\n        supplierDocType: \"6\",\n        supplierDocNumber: \"20123456786\",\n        supplierName: \"PROVEEDOR ALFA S.A.C.\",\n        baseGravadaExclusiva: \"500.00\",\n        igvGravadoExclusivo: \"90.00\",\n        totalAmount: \"590.00\",\n        currency: \"PEN\",\n      };\n\n      // Trama con dos líneas exactamente iguales\n      await expect(\n        generateRceExport(\"10445533811\", \"2026-03\", [line, { ...line }], { zip: false })\n      ).rejects.toThrow(/Comprobante duplicado detectado en RCE/);\n    });\n  });\n\n  describe(\"2. Detección en Ventas y RVIE (Registro de Ventas)\", () => {\n    it(\"generateRvieExport rechaza la generación si existen comprobantes repetidos en el mismo período\", async () => {\n      const line: SireRvieLineData = {\n        companyRuc: \"10445533811\",\n        companyName: \"JOSE BARRIENTOS\",\n        period: \"202603\",\n        car: \"1044553381101F0010000000001\",\n        issueDate: \"05/03/2026\",\n        cpeType: \"01\",\n        series: \"F001\",\n        correlative: \"1\",\n        clientDocType: \"6\",\n        clientDocNumber: \"20123456786\",\n        clientName: \"CLIENTE S.A.C.\",\n        taxableBase: \"1000.00\",\n        igvAmount: \"180.00\",\n        totalAmount: \"1180.00\",\n        currency: \"PEN\",\n      };\n\n      await expect(\n        generateRvieExport(\"10445533811\", \"2026-03\", [line, { ...line }], { zip: false })\n      ).rejects.toThrow(/Comprobante duplicado detectado en RVIE/);\n    });\n\n    it(\"sireOrchestrator.generateRvieBook bloquea la emisión si se envían comprobantes duplicados\", async () => {\n      const duplicateCpes: SireCpeInput[] = [\n        {\n          companyRuc: \"10445533811\",\n          cpeType: \"01\",\n          series: \"F001\",\n          correlative: 5,\n          issueDate: \"2026-03-05\",\n          currency: \"PEN\",\n          clientDocType: \"6\",\n          clientDocNumber: \"20123456786\",\n          clientName: \"CLIENTE S.A.\",\n          taxableBase: \"1000.00\",\n          igvAmount: \"180.00\",\n          totalAmount: \"1180.00\",\n          status: \"ACEPTADO\",\n        },\n        {\n          companyRuc: \"10445533811\",\n          cpeType: \"01\",\n          series: \"F001\",\n          correlative: 5, // Mismo tipo, serie y correlativo\n          issueDate: \"2026-03-05\",\n          currency: \"PEN\",\n          clientDocType: \"6\",\n          clientDocNumber: \"20123456786\",\n          clientName: \"CLIENTE S.A.\",\n          taxableBase: \"1000.00\",\n          igvAmount: \"180.00\",\n          totalAmount: \"1180.00\",\n          status: \"ACEPTADO\",\n        },\n      ];\n\n      await expect(\n        sireOrchestrator.generateRvieBook(company, \"2026-03\", duplicateCpes, { zip: false })\n      ).rejects.toThrow(/Comprobante duplicado detectado en RVIE/);\n    });\n\n    it(\"sireOrchestrator.checkRvieDuplicates alerta preventivamente sin lanzar excepción\", () => {\n      const duplicateCpes: SireCpeInput[] = [\n        {\n          companyRuc: \"10445533811\",\n          cpeType: \"01\",\n          series: \"F001\",\n          correlative: 8,\n          issueDate: \"2026-03-08\",\n          currency: \"PEN\",\n          clientDocType: \"6\",\n          clientDocNumber: \"20123456786\",\n          clientName: \"CLIENTE\",\n          taxableBase: \"100.00\",\n          igvAmount: \"18.00\",\n          totalAmount: \"118.00\",\n          status: \"ACEPTADO\",\n        },\n        {\n          companyRuc: \"10445533811\",\n          cpeType: \"01\",\n          series: \"F001\",\n          correlative: 8,\n          issueDate: \"2026-03-08\",\n          currency: \"PEN\",\n          clientDocType: \"6\",\n          clientDocNumber: \"20123456786\",\n          clientName: \"CLIENTE\",\n          taxableBase: \"100.00\",\n          igvAmount: \"18.00\",\n          totalAmount: \"118.00\",\n          status: \"ACEPTADO\",\n        },\n      ];\n\n      const report = sireOrchestrator.checkRvieDuplicates(duplicateCpes, \"2026-03\");\n\n      expect(report.hasDuplicates).toBe(true);\n      expect(report.duplicates).toHaveLength(1);\n      expect(report.duplicates[0]).toMatch(/10445533811 - tipo 01 F001-8/);\n      expect(report.uniqueCount).toBe(1);\n    });\n\n    it(\"permite el mismo correlativo si difieren en tipo de comprobante (ej. Factura 01 vs Boleta 03)\", async () => {\n      const lines: SireRvieLineData[] = [\n        {\n          companyRuc: \"10445533811\",\n          companyName: \"JOSE BARRIENTOS\",\n          period: \"202603\",\n          issueDate: \"05/03/2026\",\n          cpeType: \"01\", // Factura\n          series: \"F001\",\n          correlative: \"1\",\n          clientDocType: \"6\",\n          clientDocNumber: \"20123456786\",\n          clientName: \"CLIENTE 1\",\n          taxableBase: \"100.00\",\n          igvAmount: \"18.00\",\n          totalAmount: \"118.00\",\n          currency: \"PEN\",\n        },\n        {\n          companyRuc: \"10445533811\",\n          companyName: \"JOSE BARRIENTOS\",\n          period: \"202603\",\n          issueDate: \"05/03/2026\",\n          cpeType: \"03\", // Boleta\n          series: \"B001\",\n          correlative: \"1\",\n          clientDocType: \"1\",\n          clientDocNumber: \"12345678\",\n          clientName: \"CLIENTE 2\",\n          taxableBase: \"50.00\",\n          igvAmount: \"9.00\",\n          totalAmount: \"59.00\",\n          currency: \"PEN\",\n        },\n      ];\n\n      const res = await generateRvieExport(\"10445533811\", \"2026-03\", lines, { zip: false });\n      expect(res.lineCount).toBe(2);\n    });\n  });\n\n  describe(\"3. Normalización de Claves Únicas\", () => {\n    it(\"normaliza series en mayúsculas, ceros correlativos y formato de período\", () => {\n      const key1 = normalizeDuplicateKey(\"20123456786\", \"1\", \"f001\", 5, \"2026-03\");\n      const key2 = normalizeDuplicateKey(\"20123456786\", \"01\", \"F001\", \"00000005\", \"202603\");\n\n      expect(key1).toBe(\"20123456786|01|F001|00000005|202603\");\n      expect(key1).toBe(key2);\n    });\n\n    it(\"detectDuplicates identifica colisiones con distintos formatos de entrada equivalentes\", () => {\n      const items = [\n        { entityDocNumber: \"20123456786\", cpeType: \"01\", series: \"f001\", correlative: 12, period: \"2026-03\" },\n        { entityDocNumber: \"20123456786\", cpeType: \"1\", series: \"F001\", correlative: \"00000012\", period: \"202603\" },\n      ];\n\n      const result = detectDuplicates(items, \"RCE\");\n      expect(result.hasDuplicates).toBe(true);\n      expect(result.uniqueCount).toBe(1);\n    });\n  });\n});\n"
};

function install() {
  console.log("=== Instalando Módulo de Compras y SIRE con Detección de Duplicados ===");
  const projectRoot = process.cwd();

  let installedCount = 0;
  for (const [relPath, content] of Object.entries(files)) {
    const fullPath = path.join(projectRoot, relPath);
    const dir = path.dirname(fullPath);

    if (!fs.existsSync(dir)) {
      fs.mkdirSync(dir, { recursive: true });
    }

    fs.writeFileSync(fullPath, content, "utf8");
    console.log(`[OK] Creado/Actualizado: ${relPath}`);
    installedCount++;
  }

  console.log(`\nInstalación completada con éxito: ${installedCount} archivos creados/actualizados.`);
  console.log("\nComandos de verificación:");
  console.log("1. npx vitest run");
  console.log("2. npm run typecheck");
}

install();
